 ensure(TypedDataEncoder.hash(domain,executionTypes('Mandate'),mandate)===deal.mandateId&&verifyTypedData(domain,executionTypes('Mandate'),mandate,mandateSignature)===config.human,'HUMAN_MANDATE_SIGNATURE');
