 attempt.elapsed_ms=Math.round(performance.now()-start);attempt.sessions=journal.negotiation?.sessions??{};report.attempts.push(attempt);save();console.log(JSON.stringify({cap,repeat,success:attempt.success,calls:attempt.calls,tokens:attempt.total_tokens,truncations:attempt.truncations,error:attempt.error??null}));
}
report.summary=caps.map(cap=>{const a=report.attempts.filter(a=>a.cap===cap);return {cap,attempts:a.length,successful:a.filter(x=>x.success).length,clean_successful:a.filter(x=>x.success&&x.invalid_calls===0&&x.calls===5).length,total_tokens:a.reduce((n,x)=>n+(x.total_tokens??0),0),truncations:a.reduce((n,x)=>n+x.truncations,0)};});
